1	package api
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"net/http"
9		"net/url"
10		"strconv"
11		"strings"
12	
13		"github.com/gin-gonic/gin"
14	
15		"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
16		"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
17	)
18	
19	// Error codes published by the placements API.
20	const (
21		codeInvalidInput = "InvalidPlacementInputError"
22		codeNotFound     = "PlacementNotFoundError"
23		codeConflict     = "PlacementConflictError"
24		codeStorageDown  = "storage_unavailable"
25	)
26	
27	var errInvalidPlacement = errors.New("invalid placement input")
28	
29	type placementHandler struct {
30		svc *service.Service
31	}
32	
33	func writeAPIError(c *gin.Context, status int, code, message string) {
34		c.AbortWithStatusJSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
35	}
36	
37	// createPlacement handles POST /v1/placements. The transport layer only
38	// parses and validates the request and maps the business acceptance outcome
39	// to its HTTP status; scheduling and idempotency/conflict decisions belong to
40	// service.Accept.
41	func (h *placementHandler) createPlacement(c *gin.Context) {
42		body, err := io.ReadAll(c.Request.Body)
43		if err != nil {
44			writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
45			return
46		}
47		p, err := parsePlacement(body)
48		if err != nil {
49			writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
50			return
51		}
52	
53		stored, outcome, err := h.svc.Accept(c.Request.Context(), p)
54		if err != nil {
55			writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
56			return
57		}
58		switch outcome {
59		case service.Created:
60			c.JSON(http.StatusCreated, stored)
61		case service.Identical:
62			c.JSON(http.StatusOK, stored)
63		case service.Conflict:
64			writeAPIError(c, http.StatusConflict, codeConflict,
65				"a placement with this namespace and name already exists with different content")
66		}
67	}
68	
69	// listPlacements handles GET /v1/placements, both the single-record form
70	// (namespace+name) and the filtered-list form. The transport layer only
71	// decodes the raw query string and maps the business result to its HTTP
72	// status; all parameter rules and filtering belong to service.Query.
73	func (h *placementHandler) listPlacements(c *gin.Context) {
74		values, err := url.ParseQuery(c.Request.URL.RawQuery)
75		if err != nil {
76			writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
77			return
78		}
79	
80		result, err := h.svc.Query(c.Request.Context(), values)
81		if errors.Is(err, service.ErrInvalidPlacementQuery) {
82			writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
83			return
84		}
85		if errors.Is(err, service.ErrPlacementNotFound) {
86			writeAPIError(c, http.StatusNotFound, codeNotFound, "placement not found")
87			return
88		}
89		if err != nil {
90			writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
91			return
92		}
93		if result.Record != nil {
94			c.JSON(http.StatusOK, result.Record)
95			return
96		}
97		c.JSON(http.StatusOK, gin.H{"items": result.Items})
98	}
99	
100	// ---------------------------------------------------------------------------
101	// Strict request parsing.
102	//
103	// The token walk below enforces, before anything is stored:
104	//   - the body is one JSON object with exactly the documented members,
105	//   - no unknown or duplicate member names at any level,
106	//   - no trailing data after the root object,
107	//   - every value has the declared JSON type and range (null is never accepted
108	//     where a value is required; omitted selector/labels default to {}),
109	//   - node names are unique.
110	// ---------------------------------------------------------------------------
111	
112	var topLevelFields = map[string]bool{
113		"namespace": true,
114		"name":      true,
115		"queue":     true,
116		"priority":  true,
117		"resources": true,
118		"selector":  true,
119		"nodes":     true,
120	}
121	
122	var resourceFields = map[string]bool{"cpu": true, "memory": true}
123	
124	var nodeFields = map[string]bool{
125		"name":   true,
126		"cpu":    true,
127		"memory": true,
128		"labels": true,
129	}
130	
131	func parsePlacement(body []byte) (*store.Placement, error) {
132		dec := json.NewDecoder(bytes.NewReader(body))
133		dec.UseNumber()
134	
135		tok, err := dec.Token()
136		if err != nil {
137			return nil, errInvalidPlacement
138		}
139		if d, ok := tok.(json.Delim); !ok || d != '{' {
140			return nil, errInvalidPlacement
141		}
142	
143		p := &store.Placement{}
144		seen := map[string]bool{}
145		for dec.More() {
146			keyTok, err := dec.Token()
147			if err != nil {
148				return nil, errInvalidPlacement
149			}
150			key, ok := keyTok.(string)
151			if !ok || !topLevelFields[key] || seen[key] {
152				return nil, errInvalidPlacement
153			}
154			seen[key] = true
155	
156			var raw json.RawMessage
157			if err := dec.Decode(&raw); err != nil {
158				return nil, errInvalidPlacement
159			}
160	
161			switch key {
162			case "namespace", "name", "queue":
163				s, err := parseTrimmedString(raw)
164				if err != nil {
165					return nil, err
166				}
167				switch key {
168				case "namespace":
169					p.Namespace = s
170				case "name":
171					p.Name = s
172				case "queue":
173					p.Queue = s
174				}
175			case "priority":
176				n, err := parseBoundedInt(raw, 32)
177				if err != nil {
178					return nil, err
179				}
180				p.Priority = int32(n)
181			case "resources":
182				r, err := parseResources(raw)
183				if err != nil {
184					return nil, err
185				}
186				p.Resources = r
187			case "selector":
188				m, err := parseStringMap(raw)
189				if err != nil {
190					return nil, err
191				}
192				p.Selector = m
193			case "nodes":
194				nodes, err := parseNodes(raw)
195				if err != nil {
196					return nil, err
197				}
198				p.Nodes = nodes
199			}
200		}
201		if _, err := dec.Token(); err != nil {
202			return nil, errInvalidPlacement // closing '}'
203		}
204		if _, err := dec.Token(); !errors.Is(err, io.EOF) {
205			return nil, errInvalidPlacement // trailing data
206		}
207	
208		for _, required := range []string{"namespace", "name", "queue", "priority", "resources", "nodes"} {
209			if !seen[required] {
210				return nil, errInvalidPlacement
211			}
212		}
213		if p.Selector == nil {
214			p.Selector = map[string]string{}
215		}
216		return p, nil
217	}
218	
219	func parseResources(raw json.RawMessage) (store.Resources, error) {
220		var r store.Resources
221		obj, err := parseStrictObject(raw, resourceFields)
222		if err != nil {
223			return r, err
224		}
225		cpuRaw, ok := obj["cpu"]
226		if !ok {
227			return r, errInvalidPlacement
228		}
229		memoryRaw, ok := obj["memory"]
230		if !ok {
231			return r, errInvalidPlacement
232		}
233		cpu, err := parseBoundedInt(cpuRaw, 64)
234		if err != nil || cpu <= 0 {
235			return r, errInvalidPlacement
236		}
237		memory, err := parseBoundedInt(memoryRaw, 64)
238		if err != nil || memory <= 0 {
239			return r, errInvalidPlacement
240		}
241		return store.Resources{CPU: cpu, Memory: memory}, nil
242	}
243	
244	func parseNodes(raw json.RawMessage) ([]store.Node, error) {
245		if isNull(raw) {
246			return nil, errInvalidPlacement
247		}
248		dec := json.NewDecoder(bytes.NewReader(raw))
249		tok, err := dec.Token()
250		if err != nil {
251			return nil, errInvalidPlacement
252		}
253		if d, ok := tok.(json.Delim); !ok || d != '[' {
254			return nil, errInvalidPlacement
255		}
256	
257		nodes := []store.Node{}
258		names := map[string]bool{}
259		for dec.More() {
260			var elem json.RawMessage
261			if err := dec.Decode(&elem); err != nil {
262				return nil, errInvalidPlacement
263			}
264			obj, err := parseStrictObject(elem, nodeFields)
265			if err != nil {
266				return nil, err
267			}
268			nameRaw, ok := obj["name"]
269			if !ok {
270				return nil, errInvalidPlacement
271			}
272			cpuRaw, ok := obj["cpu"]
273			if !ok {
274				return nil, errInvalidPlacement
275			}
276			memoryRaw, ok := obj["memory"]
277			if !ok {
278				return nil, errInvalidPlacement
279			}
280			name, err := parseTrimmedString(nameRaw)
281			if err != nil {
282				return nil, err
283			}
284			cpu, err := parseBoundedInt(cpuRaw, 64)
285			if err != nil || cpu < 0 {
286				return nil, errInvalidPlacement
287			}
288			memory, err := parseBoundedInt(memoryRaw, 64)
289			if err != nil || memory < 0 {
290				return nil, errInvalidPlacement
291			}
292			labels := map[string]string{}
293			if labelRaw, ok := obj["labels"]; ok {
294				labels, err = parseStringMap(labelRaw)
295				if err != nil {
296					return nil, err
297				}
298			}
299			if names[name] {
300				return nil, errInvalidPlacement
301			}
302			names[name] = true
303			nodes = append(nodes, store.Node{Name: name, CPU: cpu, Memory: memory, Labels: labels})
304		}
305		if _, err := dec.Token(); err != nil {
306			return nil, errInvalidPlacement // closing ']'
307		}
308		return nodes, nil
309	}
310	
311	// parseStrictObject decodes an object whose member names are restricted to
312	// allowed. Both unknown and duplicate names are rejected.
313	func parseStrictObject(raw json.RawMessage, allowed map[string]bool) (map[string]json.RawMessage, error) {
314		if isNull(raw) {
315			return nil, errInvalidPlacement
316		}
317		dec := json.NewDecoder(bytes.NewReader(raw))
318		tok, err := dec.Token()
319		if err != nil {
320			return nil, errInvalidPlacement
321		}
322		if d, ok := tok.(json.Delim); !ok || d != '{' {
323			return nil, errInvalidPlacement
324		}
325		return readObjectMembers(dec, allowed)
326	}
327	
328	// parseStringMap decodes an object with arbitrary string keys and string
329	// values; null or non-string values are rejected.
330	func parseStringMap(raw json.RawMessage) (map[string]string, error) {
331		if isNull(raw) {
332			return nil, errInvalidPlacement
333		}
334		dec := json.NewDecoder(bytes.NewReader(raw))
335		tok, err := dec.Token()
336		if err != nil {
337			return nil, errInvalidPlacement
338		}
339		if d, ok := tok.(json.Delim); !ok || d != '{' {
340			return nil, errInvalidPlacement
341		}
342	
343		out := map[string]string{}
344		raws, err := readObjectMembers(dec, nil)
345		if err != nil {
346			return nil, err
347		}
348		for key, value := range raws {
349			s, err := parseJSONString(value)
350			if err != nil {
351				return nil, err
352			}
353			out[key] = s
354		}
355		return out, nil
356	}
357	
358	func readObjectMembers(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
359		out := map[string]json.RawMessage{}
360		for dec.More() {
361			keyTok, err := dec.Token()
362			if err != nil {
363				return nil, errInvalidPlacement
364			}
365			key, ok := keyTok.(string)
366			if !ok {
367				return nil, errInvalidPlacement
368			}
369			if allowed != nil && !allowed[key] {
370				return nil, errInvalidPlacement
371			}
372			if _, dup := out[key]; dup {
373				return nil, errInvalidPlacement
374			}
375			var value json.RawMessage
376			if err := dec.Decode(&value); err != nil {
377				return nil, errInvalidPlacement
378			}
379			out[key] = value
380		}
381		if _, err := dec.Token(); err != nil {
382			return nil, errInvalidPlacement // closing '}'
383		}
384		return out, nil
385	}
386	
387	// parseTrimmedString accepts a JSON string that is non-empty and has no
388	// leading or trailing Unicode whitespace.
389	func parseTrimmedString(raw json.RawMessage) (string, error) {
390		s, err := parseJSONString(raw)
391		if err != nil {
392			return "", err
393		}
394		if s == "" || s != strings.TrimSpace(s) {
395			return "", errInvalidPlacement
396		}
397		return s, nil
398	}
399	
400	func parseJSONString(raw json.RawMessage) (string, error) {
401		if isNull(raw) {
402			return "", errInvalidPlacement
403		}
404		var s string
405		if err := json.Unmarshal(raw, &s); err != nil {
406			return "", errInvalidPlacement
407		}
408		return s, nil
409	}
410	
411	// parseBoundedInt accepts an integral JSON number without fraction or exponent
412	// that fits a signed integer of the given bit size (32 or 64).
413	func parseBoundedInt(raw json.RawMessage, bitSize int) (int64, error) {
414		if isNull(raw) {
415			return 0, errInvalidPlacement
416		}
417		dec := json.NewDecoder(bytes.NewReader(raw))
418		dec.UseNumber()
419		var value any
420		if err := dec.Decode(&value); err != nil {
421			return 0, errInvalidPlacement
422		}
423		number, ok := value.(json.Number)
424		if !ok {
425			return 0, errInvalidPlacement
426		}
427		n, err := strconv.ParseInt(number.String(), 10, bitSize)
428		if err != nil {
429			return 0, errInvalidPlacement
430		}
431		return n, nil
432	}
433	
434	func isNull(raw json.RawMessage) bool {
435		return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
436	}
