407			`{"namespace":"ns","name":"job","queue":"q","priority":1,
408			  "resources":{"cpu":9223372036854775808,"memory":1},"nodes":[]}`, // int64 overflow
409			`{"namespace":"ns","name":"job","queue":"q","priority":1,
410			  "resources":{"cpu":100,"memory":64},"nodes":{}}`, // nodes not array
411			`{"namespace":"ns","name":"job","queue":"q","priority":1,
412			  "resources":{"cpu":100,"memory":64},"nodes":null}`, // null nodes
413			`{"namespace":"ns","name":"job","queue":"q","priority":1,
414			  "resources":{"cpu":100,"memory":64},
415			  "nodes":[{"name":"n1","cpu":-1,"memory":64}]}`, // negative node cpu
416			`{"namespace":"ns","name":"job","queue":"q","priority":1,
417			  "resources":{"cpu":100,"memory":64},
418			  "nodes":[{"name":"n1","cpu":100,"memory":64},
419			           {"name":"n1","cpu":100,"memory":64}]}`, // duplicate node names
420			`{"namespace":"ns","name":"job","queue":"q","priority":1,
421			  "resources":{"cpu":100,"memory":64},
422			  "nodes":[{"name":"","cpu":100,"memory":64}]}`, // empty node name
423			`{"namespace":"ns","name":"job","queue":"q","priority":1,
424			  "resources":{"cpu":100,"memory":64},
425			  "nodes":[{"name":123,"cpu":100,"memory":64}]}`, // numeric node name
426			`{"namespace":"ns","name":"job","queue":"q","priority":1,
427			  "resources":{"cpu":100,"memory":64},
428			  "nodes":[{"name":"n1","cpu":100,"memory":64,"labels":null}]}`, // null labels
429			`{"namespace":"ns","name":"job","queue":"q","priority":1,
430			  "resources":{"cpu":100,"memory":64},"selector":null,"nodes":[]}`, // null selector
431			`{"namespace":"ns","name":"job","queue":"q","priority":1,
432			  "resources":{"cpu":100,"memory":64},"selector":{"k":1},"nodes":[]}`, // non-string label value
433		}
434		for i, body := range rawCases {
435			rec := postPlacement(t, h, body)
436			if rec.Code != http.StatusBadRequest {
437				t.Errorf("case %d: status = %d, want 400; body %s", i, rec.Code, rec.Body.String())
438				continue
439			}
440			expectErrorCode(t, rec, http.StatusBadRequest, "InvalidPlacementInputError")
441		}
442	
443		// Rejected input must not have been stored.
444		list := doRequest(t, h, http.MethodGet, "/v1/placements?namespace=ns", "")
445		if items := decodeBody(t, list)["items"].([]any); len(items) != 0 {
446			t.Fatalf("invalid bodies stored %d records", len(items))
447		}
448	}
