450	func TestBoundaryValuesAccepted(t *testing.T) {
451		_, h := newTestRouter(t)
452		body := `{
453		  "namespace": "ns", "name": "job", "queue": "q",
454		  "priority": 2147483647,
455		  "resources": {"cpu": 9223372036854775807, "memory": 1},
456		  "nodes": [{"name": "n", "cpu": 0, "memory": 0, "labels": {}}]
457		}`
