479		if bytes.Contains(rec.Body.Bytes(), []byte("SQLITE")) || bytes.Contains(rec.Body.Bytes(), []byte(".go")) {
480			t.Fatalf("503 body leaks internals: %s", rec.Body.String())
481		}
