		t.Fatalf("omitted selector must default to an empty object, got %#v", p.Selector)
	}
	if p.Nodes[0].Labels == nil || len(p.Nodes[0].Labels) != 0 {
		t.Fatalf("omitted labels must default to an empty object, got %#v", p.Nodes[0].Labels)
