	q, err := ParsePlacementInput([]byte(empty))
	if err != nil {
		t.Fatalf("parse: %v", err)
	}
	if q.Nodes == nil || len(q.Nodes) != 0 {
		t.Fatalf("empty nodes must stay an empty array, got %#v", q.Nodes)
	}
